public interface WeaponFactory {
    Weapon create(WeaponType name);

    static WeaponFactory factory(Consumer<Builder> configure) {
        var map = new HashMap<WeaponType, Supplier<Weapon>>();
        configure.accept(map::put);                       // Builder.add(name, supplier)
        return name -> {
            var builder = map.get(name);
            if (builder == null) throw new IllegalArgumentException("unknown weapon: " + name);
            return builder.get();
        };
    }
}
